def solve(**p):
    P = float(p['principal'])
    rate = float(p['annual_rate_percent']) / 100.0
    n = int(round(float(p['num_payments'])))
    m = float(p.get('periods_per_year', 12) or 12)
    r = rate / m
    if r == 0:
        pmt = P / n
    else:
        pmt = P * r / (1 - (1 + r) ** (-n))
    from decimal import Decimal, ROUND_HALF_UP
    return str(Decimal(repr(pmt)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

