def solve(**p):
    import math
    def tm(s):
        h, m = str(s).strip().split(':')
        return int(h) * 60 + float(m)
    D = float(p['distance_km'])
    ta = tm(p['depart_a']); tb = tm(p['depart_b'])
    va = float(p['speed_a']); vb = float(p['speed_b'])
    if ta <= tb:
        te, ve, tl = ta, va, tb
    else:
        te, ve, tl = tb, vb, ta
    head = ve * (tl - te) / 60.0
    if head >= D:
        meet = te + D / ve * 60.0
    else:
        meet = tl + (D - head) / (va + vb) * 60.0
    m = int(math.floor(meet + 0.5 + 1e-9)) % 1440
    return '%02d:%02d' % (m // 60, m % 60)

