def solve(**p):
    import datetime
    d = datetime.date.fromisoformat(str(p['start_date']).strip())
    n = int(p['business_days'])
    step = 1 if n >= 0 else -1
    remaining = abs(n)
    while remaining > 0:
        d += datetime.timedelta(days=step)
        if d.weekday() < 5:
            remaining -= 1
    return d.isoformat()
